schema:
{
  "description": "Fatture fornitori italiane",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "estimateFieldSourceAndConfidence": true
  },
  "fieldSchema": {
    "fields": {
      "Fornitore": {
        "type": "string",
        "method": "extract",
        "description": "Ragione sociale del fornitore, in alto a sinistra, prima dell'indirizzo."
      },
      "PartitaIVA": {
        "type": "string",
        "method": "extract",
        "description": "Partita IVA del fornitore, preceduta da \"P.IVA\", con o senza prefisso IT."
      },
      "NumeroFattura": {
        "type": "string",
        "method": "extract",
        "description": "Numero dopo \"FATTURA N.\" in alto a destra."
      },
      "DataEmissione": {
        "type": "date",
        "method": "extract",
        "description": "Data della fattura, etichettata \"Data\", in alto a destra."
      },
      "GiorniPagamento": {
        "type": "number",
        "method": "extract",
        "description": "Numero di giorni nella riga \"Pagamento\", per esempio 30 in \"30 gg data fattura\"."
      },
      "Righe": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "Descrizione": {
              "type": "string"
            },
            "Quantita": {
              "type": "number"
            },
            "Importo": {
              "type": "number"
            }
          }
        }
      },
      "Imponibile": {
        "type": "number",
        "method": "extract",
        "description": "Importo prima dell'IVA; può chiamarsi \"Imponibile\" o \"Totale parziale\"."
      },
      "Totale": {
        "type": "number",
        "method": "extract",
        "description": "Importo finale dopo l'IVA, etichettato \"Totale documento\", in fondo."
      }
    }
  }
}
